/* 좌하단 코너 — Mapbox logo 위에 배치 (저작권 표시 가림 방지) */

.route-dock-anchor {
  --route-dock-pad: clamp(0.45rem, 1.4vw, 0.85rem);
  position: absolute;
  left: max(var(--route-dock-pad), env(safe-area-inset-left, 0px));
  bottom: calc(
    max(var(--route-dock-pad), env(safe-area-inset-bottom, 0px)) + var(--mapbox-logo-clearance, 2.875rem)
  );
  /*
   * MapHud(z-index 5) 보다 위. 폰 가로처럼 세로가 짧으면 하단 앵커인 이 패널이 위로
   * 올라와 좌상단 접속 패널과 겹치는데, 그때 「조작(Go)」이 「정보(접속 현황)」에
   * 가려지면 안 된다. 실제로 「다른 라이더 없음」 문구가 Go 탭을 가로챘다.
   */
  z-index: 6;
  max-width: min(21.6rem, calc(100vw - 2rem));
  pointer-events: none;
}

/* 단일 글래스 틀 — caret + 패널을 한 덩어리로 감싸 일체화 */
.route-dock__shell {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 0;
  pointer-events: auto;
  border: 1px solid #CBD5E1;
  border-radius: var(--rtw-radius, 14px);
  background: #FFFFFF;
  -webkit-backdrop-filter: blur(var(--rtw-glass-blur, 12px));
  backdrop-filter: blur(var(--rtw-glass-blur, 12px));
  box-shadow: var(--rtw-glass-shadow, 4px 8px 28px rgba(2, 8, 20, 0.4));
  overflow: hidden;
}

.route-dock__caret {
  flex: 0 0 auto;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.3rem;
  /* 폭 60% 축소(2026-09-18 Chief) — 1.55rem → 0.93rem. 공간을 아낀다.
     세로 44px 히트는 유지(가로는 「경로」 글자 제거 이전부터 44px 미만 — 별건). */
  width: 0.93rem;
  /*
   * 터치 타깃 44px — 「44px 이상, rem 금지」(f046ce5). 세로 텍스트 「경로」를 빼면서
   * 높이를 벌어주던 지지대가 사라져 폰 가로(루트 13.5px)에서 2.75rem = 약 37px 로
   * 줄었다. 배경이 transparent 이고 보이는 것은 14px 셰브런뿐이라, 버튼의 실제 높이를
   * 키워도 시각적 비용이 없다 — `::after` 투명 히트 영역은 여기서 쓸 수 없다.
   * 부모 `.route-dock__shell { overflow: hidden }` 이 caret 테두리 1px 바깥에서
   * 잘라내 밖으로 뻗는 히트 영역이 elementFromPoint 에 잡히지 않기 때문이다.
   * 가로(1.55rem = 약 21px)는 「경로」와 무관하게 원래부터 44px 미만 — 넓히면 dock
   * 접힘 폭이 커지므로 Chief 판단 대기(별건).
   */
  min-height: 44px;
  padding: 0.4rem 0;
  border: none;
  background: transparent;
  color: #475569;
  cursor: pointer;
  transition: background 0.14s ease, color 0.14s ease;
}

/* 펼침 시 구분선 없음 — caret 는 hover 로만 구분 (틀은 shell 단일) */
.route-dock-anchor--open .route-dock__caret {
  min-height: 0;
}

.route-dock__caret:hover {
  background: #EFF6FF;
  color: #1F2937;
}

/* boxcycle-theme.css §2 `.hud-glass`(뒤에 로드, 명시도 0,1,0)가 다크 글래스를 덮으므로
   dock 스코프에서 색만 보정 — 배치·블러 등 비색상 선언은 테마 그대로. */
.route-dock__caret.hud-glass {
  background: #FFFFFF;
  border-color: #CBD5E1;
}

.route-dock__caret.hud-glass:hover {
  background: #EFF6FF;
  border-color: #CBD5E1;
}

.route-dock__caret-icon {
  display: block;
}

/* 주행 중 접힘 — 셰브런 자리의 센서 LED(지시01 §3). 색은 cadenceChipView 계약만. */
.route-dock__caret-led {
  display: block;
  /* 캐럿 폭(0.93rem) 안에서 보이도록 칩 LED 보다 살짝 작게 */
  width: 0.45rem;
  height: 0.45rem;
}

/*
 * 접힘(주행 중 · 첫 화면 둘 다): body 가 빈 채 flex 로 폭을 먹지 않게.
 * top:empty → display:none, panel[hidden] → 숨김 → shell = 캐럿 폭만.
 */
.route-dock-anchor--ride-collapsed .route-dock__body,
.route-dock-anchor--caret-only .route-dock__body {
  flex: 0 0 auto;
  width: 0;
  min-width: 0;
  overflow: hidden;
}


/*
 * caret 오른쪽 세로 스택 — 첫 행(항상 보임) + 접히는 본문.
 * 접으면 본문이 display:none 이라 폭이 첫 행(=센서 칩)만큼으로 줄어든다.
 */
.route-dock__body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

/*
 * 첫 행 — 센서 칩 + Go·저장·삭제. `route-dock__panel` 밖이라 접어도 칩이 남는다.
 * 칩이 없고 접혀 있으면 빈 껍데기가 되므로 `:empty` 로 지운다.
 */
.route-dock__top {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  box-sizing: border-box;
  /* 왼쪽 0 — 칩·주소가 캐럿에 바로 붙는다(2026-09-18 Chief: 왼쪽 빈 공간 없게) */
  padding: 0.5rem 0.55rem 0 0;
  /*
   * 본문(hud-glass)과 같은 면. `hud-glass` 클래스를 붙이지 않는 이유는 그 1px 테두리가
   * dock 높이를 2px 키우기 때문 — 「칩을 넣어도 dock 크기는 그대로」를 지킨다.
   */
  background: #FFFFFF;
  color: #1F2937;
  font-family: var(--rtw-font, inherit);
}

.route-dock__top:empty {
  display: none;
}

/* 첫 행이 이미 위 여백을 냈으므로 본문은 행 간격만 남긴다 */
.route-dock-anchor--open .route-dock__panel {
  padding-top: 0.45rem;
}

.route-dock__panel {
  flex: 1 1 auto;
  min-width: 0;
  /*
   * 가로 80% 축소(2026-09-18 Chief) — 21rem → 16rem, 폰 가로는 17.5 → 13.32rem.
   * 캐럿(12.55px)·테두리(2px)는 고정이라 패널만 20% 줄이면 dock 전체는 83.8% 에 그친다.
   * dock 전체 기준으로 맞춘다: 실측 243.00px → 목표 194.40px → 패널 179.85px = 13.32rem.
   */
  width: min(16rem, calc(100vw - 2.5rem));
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  /* 왼쪽 0 — 출발·도착 주소가 왼쪽 끝에 붙는다(2026-09-18 Chief) */
  padding: 0.5rem 0.55rem 0.55rem 0;
  background: transparent;
  color: #1F2937;
  font-family: var(--rtw-font, inherit);
  max-height: min(40vh, 16.5rem);
  overflow: hidden;
  animation: route-dock-panel-in 0.2s ease;
}

.route-dock__panel[hidden] {
  display: none;
}

@keyframes route-dock-panel-in {
  from {
    opacity: 0;
    transform: translateX(-0.35rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.route-dock__head {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.35rem;
}

/*
 * 주행 제어(Go · 일시정지 · 종료) — 2026-09-28 Chief.
 * 세 버튼은 항상 같은 자리·같은 크기다. 상태에 따라 사라지지 않으므로 줄 폭이
 * 흔들리지 않고, 종료 버튼의 위치가 몸에 남는다.
 */
.route-dock__transport {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.3rem;
  margin-left: auto;
  flex: 0 0 auto;
}

.route-dock__transport-btn {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.1rem;
  height: 2.1rem;
  padding: 0;
  border: 1px solid #CBD5E1;
  border-radius: 999px;
  background: #F1F5F9;
  color: #475569;
  appearance: none;
  cursor: pointer;
}

.route-dock__transport-btn:hover:not(:disabled) {
  border-color: #2563EB;
  background: #EFF6FF;
}

.route-dock__transport-btn:disabled {
  opacity: 0.32;
  cursor: not-allowed;
}

.route-dock__transport-btn--stop:hover:not(:disabled) {
  border-color: rgba(220, 38, 38, 0.5);
  color: #DC2626;
}

/* 이어 달리기(§9.5.5 단위7) — 미완주 저장 경로 로드 시 재개/처음부터 선택 */
.route-dock__resume {
  display: flex;
  align-items: stretch;
  gap: 0.4rem;
  flex: 0 0 auto;
  padding: 0.32rem 0.4rem;

  background: rgba(220, 38, 38, 0.12);
  border-color: rgba(220, 38, 38, 0.4);
  color: #DC2626;
}

.route-dock__stop-remove:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

/* Go 만 채운 알약 — 셋 중 유일한 「진행」 동작이라 색으로 구분한다. */
.route-dock__go {
  border: 0;
  background: #2563EB;
  color: #FFFFFF;
  box-shadow: 0 3px 12px rgba(37, 99, 235, 0.35);
}

.route-dock__go:hover:not(:disabled) {
  filter: brightness(1.06);
  background: #1D4ED8;
  border: 0;
}

.route-dock__go:disabled {
